package com.bank.warch;

import java.util.*;
import java.util.logging.*;

public class WellArchitectedDemo {
    private static final Logger log = Logger.getLogger("WellArchitected");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        WellArchitectedReview review = new WellArchitectedReview("payments-service", 3 /*min score*/);
        review.add(new Pillar("Operational Excellence", 4, "runbooks exist; add automated rollback"));
        review.add(new Pillar("Security", 4, "least-privilege IAM; enable GuardDuty"));
        review.add(new Pillar("Reliability", 2, "single-AZ RDS, no automatic failover"));
        review.add(new Pillar("Performance Efficiency", 3, "right-size ECS tasks under load test"));
        review.add(new Pillar("Cost Optimization", 2, "no cost tags; idle dev env runs 24x7"));
        review.add(new Pillar("Sustainability", 4, "efficient region + right-sized instances"));

        for (Pillar p : review.pillars()) {
            log.info(() -> p.name() + ": score " + p.score() + "/5 — risk: " + p.topRisk());
        }

        boolean ready = review.isProductionReady();
        if (ready) {
            log.info(() -> "Review result: PRODUCTION-READY (all pillars >= min)");
        } else {
            log.severe(() -> "Review result: NOT READY — fix weak pillars first:");
            review.weakPillars().forEach(p ->
                log.warning(() -> "  PRIORITY: " + p.name() + " (" + p.score() + "/5) -> " + p.topRisk()));
        }
    }
}

