class WellArchitectedReview {
    private final String workload;
    private final int minScore;
    private final List<Pillar> pillars = new ArrayList<>();

    WellArchitectedReview(String workload, int minScore) {
        this.workload = workload; this.minScore = minScore;
    }
    void add(Pillar p) { pillars.add(p); }
    List<Pillar> pillars() { return pillars; }

    boolean isProductionReady() {
        return pillars.stream().allMatch(p -> p.score() >= minScore);
    }
    // Weakest pillars first, so the team fixes the biggest risks first.
    List<Pillar> weakPillars() {
        return pillars.stream()
                .filter(p -> p.score() < minScore)
                .sorted(Comparator.comparingInt(Pillar::score))
                .toList();
    }
}

// ─── Would be in Pillar.java ───
class Pillar {
    private final String name;
    private final int score;      // 1..5
    private final String topRisk;
    Pillar(String name, int score, String topRisk) {
        this.name = name; this.score = score; this.topRisk = topRisk;
    }
    String name() { return name; }
    int score() { return score; }
    String topRisk() { return topRisk; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
